/* Idea Studio is adopted by the landing route first. Legacy screens retain their tokens. */
:root {
  --studio-canvas: #ffffff;
  --studio-ink: #192438;
  --studio-muted: #596477;
  --studio-blue: #3154d9;
  --studio-blue-hover: #2542b3;
  --studio-blue-light: #eef2ff;
  --studio-apricot: #ffd8c3;
  --studio-line: #dde2ec;
  --studio-soft: #f6f8fc;
}
body:has(.studio-landing) { background: var(--studio-canvas); }
.studio-landing, .studio-header { font-family: var(--font-studio), sans-serif; color: var(--studio-ink); }
.studio-landing { max-width: 1200px; margin: 0 auto; padding: 0 40px; }
.studio-landing h1, .studio-landing h2, .studio-landing h3, .studio-landing h4 { font-family: inherit; }
.studio-landing ::selection, .studio-header ::selection { background: var(--studio-apricot); color: var(--studio-ink); }
.studio-landing a:focus-visible, .studio-landing button:focus-visible, .studio-landing textarea:focus-visible,
.studio-header a:focus-visible, .studio-header button:focus-visible, .studio-header summary:focus-visible {
  outline: 3px solid var(--studio-blue); outline-offset: 4px;
}
.studio-header { border-bottom: 1px solid var(--studio-line); background: var(--studio-canvas); }
.studio-header-inner { max-width: 1200px; margin: auto; padding: 0 40px; height: 88px; display: flex; align-items: center; gap: 36px; }
.studio-header .studio-brand { color: var(--studio-ink); font-size: 25px; font-weight: 800; letter-spacing: -.04em; }
